cat=json.load(open("/sessions/inspiring-exciting-noether/mnt/Projects--RTM View Shell/docs/metrics-catalog.json"))
active=[m for m in cat["metrics"] if m.get("status")=="active"]
import re
def cl(s): return re.sub(r"\s+"," ",(s or "")).strip()
mrows=[]
for m in sorted(active,key=lambda x:(x.get("metricFunction",""),x.get("metricId",""))):
    mrows.append((m.get("metricId",""),(m.get("displayName") or m.get("originalDescription") or m.get("metricId")),m.get("metricFunction",""),cl(m.get("metricParameter","")) or "—"))

def code(lines): return '<pre class="code">'+ "\n".join(esc(l) for l in lines) +'</pre>'
def tbl(headers, rows, cls="data-table"):
    h="".join(f"<th>{esc(x)}</th>" for x in headers)
    body=""
    for r in rows:
        body+="<tr>"+"".join(f"<td>{esc(c)}</td>" for c in r)+"</tr>"
    return f'<table class="{cls}"><thead><tr>{h}</tr></thead><tbody>{body}</tbody></table>'
def callout(kind,title,inner): return f'<div class="callout {kind}"><div class="callout-title">{esc(title)}</div>{inner}</div>'

