# PART 2 - dictionary
H.append('<section class="page">')
H.append('<h1 class="section">Part 2 — The practical guide</h1>')
H.append('<span class="badge">For the BI team · SQL</span>')
H.append(callout("note","Sample tenant used throughout",
 '<p style="margin:0"><code>TenantId</code>=<code>11111111-…-111111111111</code>; all examples filter <code>OnDate=\'2026-06-09\'</code>. BUs: <strong>Sales</strong>(10), <strong>Support</strong>(20). Queues <code>SALES_VOICE, SALES_CB→Sales</code>; <code>SUP_VOICE→Support</code>. Agents <code>agent.dana, agent.omri</code> → <code>AG_SALES_1</code> → <strong>Sales Team A</strong>(100) → Sales(10).</p>'))
H.append('<h2 class="sub">2.1 Data dictionary</h2>')
H.append('<h3 class="sub3">RTSData_Interaction — call fact</h3>'+tbl(["Column","Type","Key","Meaning"],interaction))
H.append(foot("Part 2",4)+'</section>')

H.append('<section class="page">')
H.append('<h3 class="sub3">RTSData_UserStatus — today’s status totals</h3>'+tbl(["Column","Type","Key","Meaning"],userstatus))
H.append('<h3 class="sub3">RTSData_UserStatusLog — status timeline</h3>')
H.append(callout("warn","Units trap",'<p style="margin:0"><strong>UserStatusLog.Duration = MILLISECONDS</strong> (÷1000); UserStatus.TotalDuration/MaxDuraction and Interaction.TimeInQueue/TalkTime = <strong>SECONDS</strong>.</p>'))
