H.append(foot("Part 2",5)+'</section>')

# joins + gotchas + status config
H.append('<section class="page">')
H.append('<h2 class="sub">2.2 The two roll-up paths</h2>')
H.append('<p><strong>Path A — calls:</strong> Workgroup → Queue → BU (ClassificationId=\'ALL\').</p>')
H.append(code(['FROM "RTSData_Interaction" i','JOIN "NGC_BusinessUnitQueueClassification" qc',
 '  ON qc."TenantId"=i."TenantId" AND qc."QueueId"=i."Workgroup" AND qc."ClassificationId"=\'ALL\'',
 'JOIN "NGC_BusinessUnit" bu ON bu."TenantId"=qc."TenantId" AND bu."BusinessUnitId"=qc."BusinessUnitId"']))
H.append('<p><strong>Path B — agent status:</strong> UserId → AgentGroup → SuperGroup → BU.</p>')
H.append(code(['FROM "RTSData_UserStatus" us',
 'JOIN "NGC_UserAgentgroup" ua ON ua."TenantId"=us."TenantId" AND ua."UserId"=us."UserId"',
 'JOIN "NGC_SupergroupAgentgroup" sa ON sa."AgentgroupId"=ua."AgentgroupId" AND sa."TenantId"=ua."TenantId"',
 'JOIN "NGC_Supergroup" sg ON sg."SupergroupId"=sa."SupergroupId" AND sg."TenantId"=sa."TenantId"',
 'JOIN "NGC_BusinessUnitSupergroup" bs ON bs."SupergroupId"=sg."SupergroupId" AND bs."TenantId"=sg."TenantId"',
 'JOIN "NGC_BusinessUnit" bu ON bu."BusinessUnitId"=bs."BusinessUnitId" AND bu."TenantId"=bs."TenantId"']))
H.append('<h2 class="sub">2.3 Units &amp; gotchas</h2>')
H.append(tbl(["Gotcha","What it means"],[
 ["ms vs seconds","UserStatusLog.Duration=ms; UserStatus/Interaction durations=seconds."],
 ["“MaxDuraction” mis-spelled","Quote the column exactly."],
 ["OnDate is varchar","Compare as text: \"OnDate\" = '2026-06-09'."],
 ["Workgroup = queue","Join to NGC_Queues.ExternalId."],
 ["String keys, not PKs","Join on external string ids / integer BU/SG ids, not uuid PKs."],
 ["ClassificationId='ALL'","Required on the queue→BU join."],
 ["Segment grain","count(DISTINCT InteractionId) for call volumes."],
 ["TenantId everywhere","Every WHERE and JOIN carries TenantId."]],"aud-table"))
H.append('<h2 class="sub">2.4 Status-group config &amp; the trap</h2>')
H.append(callout("warn","ONPHONE double-count trap",'<p style="margin:0">In the sample tenant the ONPHONE group already <strong>contains Hold + Wrap</strong>, so StatusGroup=\'ONPHONE\' = talk+hold+wrap ≈ AHT. Compute Talk/Hold/Wrap by <strong>state</strong> and sum; do not add the ONPHONE group total on top.</p>'))
H.append(foot("Part 2",6)+'</section>')

# worked examples A & B
H.append('<section class="page">')
H.append('<h2 class="sub">2.5 Example A — abandoned Sales calls yesterday</h2>')
H.append(tbl(["Field","CALL-1001","CALL-1002","CALL-1003","CALL-1004"],[
 ["Workgroup","SALES_VOICE","SALES_VOICE","SALES_CB","SUP_VOICE"],["IsAnswered","true","false","false","false"],
 ["IsAbandoned","false","true","true","true"]],"aud-table"))
H.append(code(['SELECT count(DISTINCT i."InteractionId") AS sales_abandoned',
 'FROM "RTSData_Interaction" i',
 'JOIN "NGC_BusinessUnitQueueClassification" qc ON qc."TenantId"=i."TenantId" AND qc."QueueId"=i."Workgroup" AND qc."ClassificationId"=\'ALL\'',
 'JOIN "NGC_BusinessUnit" bu ON bu."TenantId"=qc."TenantId" AND bu."BusinessUnitId"=qc."BusinessUnitId"',
 'WHERE i."TenantId"=\'…\' AND i."OnDate"=\'2026-06-09\' AND bu."BusinessUnitName"=\'Sales\' AND i."IsAbandoned"=true;']))
H.append(callout("ok","Result",'<p style="margin:0"><strong>sales_abandoned = 2</strong> (CALL-1002, CALL-1003).</p>'))
H.append('<h2 class="sub">2.6 Example B — break-time share per Super Group</h2>')
H.append(tbl(["UserId","StatusGroup","TotalDuration (s)"],[
 ["agent.dana","AVAILABLE","10800"],["agent.dana","ONPHONE","14400"],["agent.dana","BREAK","1800"],
 ["agent.omri","AVAILABLE","7200"],["agent.omri","ONPHONE","18000"],["agent.omri","BREAK","3600"]],"aud-table"))
H.append(code(['SELECT sg."SupergroupName",',
 '  round(100.0*sum(CASE WHEN us."StatusGroup"=\'BREAK\' THEN us."TotalDuration" ELSE 0 END)/nullif(sum(us."TotalDuration"),0),2) AS break_share_pct',
 'FROM "RTSData_UserStatus" us',
 'JOIN "NGC_UserAgentgroup" ua ON ua."TenantId"=us."TenantId" AND ua."UserId"=us."UserId"',
 'JOIN "NGC_SupergroupAgentgroup" sa ON sa."AgentgroupId"=ua."AgentgroupId" AND sa."TenantId"=ua."TenantId"',
 'JOIN "NGC_Supergroup" sg ON sg."SupergroupId"=sa."SupergroupId" AND sg."TenantId"=sa."TenantId"',
 'WHERE us."TenantId"=\'…\' AND us."OnDate"=\'2026-06-09\' GROUP BY sg."SupergroupName";']))
H.append(callout("ok","Result",'<p style="margin:0"><strong>Sales Team A → 9.68%</strong> (5400 ÷ 55800).</p>'))
H.append(foot("Part 2",7)+'</section>')

# examples C & D
H.append('<section class="page">')
H.append('<h2 class="sub">2.7 Example C — Talk/Hold/Wrap/AHT = live grid</h2>')
H.append('<p>UserStatusLog for agent.dana (Duration in <strong>ms</strong>): Talk 180k+240k+300k, Hold 30k+45k, Wrap 60k+60k+90k.</p>')
H.append(code(['SELECT l."StatusId" AS state, sum(l."Duration")/1000.0 AS seconds  -- ms',
 'FROM "RTSData_UserStatusLog" l',
 'WHERE l."TenantId"=\'…\' AND l."OnDate"=\'2026-06-09\' AND l."UserId"=\'agent.dana\'',
 '  AND l."StatusId" IN (\'Talk\',\'Hold\',\'Wrap Up\') GROUP BY l."StatusId";']))
H.append(callout("ok","Parity",'<p style="margin:0">Talk 720 s · Hold 75 s · Wrap 210 s → <strong>AHT 1005 s = 16:45</strong> over 3 calls = 335 s/call — equals the live grid. ONPHONE <em>group</em> total (1005 s) ≈ AHT; for talk-only use the Talk <strong>state</strong>.</p>'))
H.append('<h2 class="sub">2.8 Example D — point-in-time wallboard at 11:30</h2>')
H.append(code(['SELECT l."UserId", l."StatusId", l."StatusGroup"',
 'FROM "RTSData_UserStatusLog" l',
 'WHERE l."TenantId"=\'…\' AND l."OnDate"=\'2026-06-09\'',
 '  AND l."StartTime" <= \'2026-06-09 11:30:00+00\'',
 '  AND (l."EndTime" > \'2026-06-09 11:30:00+00\' OR l."EndTime" IS NULL);']))
H.append(callout("ok","Result",'<p style="margin:0">11:30 → <strong>dana = Talk (ONPHONE)</strong>, <strong>omri = Break (BREAK)</strong> — exactly the live wallboard.</p>'))
H.append('<h2 class="sub">2.10 Common mistakes</h2>')
H.append('<ul><li>Mixing ms and seconds.</li><li>Adding the ONPHONE group to talk-only.</li><li><strong>Folding SIGNOFF into UNAVAILABLE.</strong></li><li>Dropping ClassificationId=\'ALL\'.</li><li>Joining on uuid PKs.</li><li>Counting segments as calls.</li><li>Missing TenantId.</li></ul>')
H.append(foot("Part 2",8)+'</section>')

# Real Time Metrics Table intro + examples
H.append('<section class="page">')
H.append('<h1 class="section">Real Time Metrics Table</h1>')
H.append('<p class="lead">This is the <code>RTSGrid_Metric</code> catalogue — every metric RTM streams in real time. <strong>To obtain historical data identical to the live figures, build your SQL filters as shown in the Metric Parameter column.</strong></p>')
H.append(callout("note","How to read Metric Parameter",
 '<ul style="margin:.04in 0">'
 '<li><strong>Interaction metrics</strong> — boolean expr over RTSData_Interaction. Translate <code>==→=</code>, <code>&amp;&amp;→AND</code>, <code>||→OR</code>, <code>!x→NOT x</code>.</li>'
 '<li><strong>Agent-status metrics</strong> — the parameter is a StatusGroup or StatusName value; filter RTSData_UserStatus/Log.</li>'
 '<li><strong>Calc metrics</strong> — a formula over other [metrics]; build each, then apply the arithmetic.</li>'
 '<li><strong>Empty</strong> — identity/text metric; no direct filter.</li></ul>'))
H.append('<h3 class="sub3">Example 1 — QueueNumAbandonedCalls</h3>')
H.append('<p>Metric Parameter: <code>(InteractionType=="Call") &amp;&amp; (CallType=="External") &amp;&amp; Direction=="Incoming" &amp;&amp; IsAbandoned &amp;&amp; !IsCallbackRequest</code></p>')
H.append(code(['WHERE i."InteractionType"=\'Call\' AND i."CallType"=\'External\'',
 '  AND i."Direction"=\'Incoming\' AND i."IsAbandoned"=true AND i."IsCallbackRequest"=false']))
H.append('<h3 class="sub3">Example 2 — MonAgentBreakDuration (param BREAK)</h3>')
H.append(code(['SELECT sum(us."TotalDuration") FROM "RTSData_UserStatus" us',
 'WHERE us."StatusGroup"=\'BREAK\'  -- TotalStatusGroupDuration, seconds']))
H.append('<h3 class="sub3">Example 3 — MonAgentNumberOfInboundCalls15sec</h3>')
H.append('<p>Metric Parameter: <code>CallType=="External" &amp;&amp; Direction=="Incoming" &amp;&amp; TalkTime&lt;15 &amp;&amp; (InteractionType=="Call" || InteractionType=="Callback")</code></p>')
H.append(code(['WHERE i."CallType"=\'External\' AND i."Direction"=\'Incoming\'',
 '  AND i."TalkTime"<15 AND i."InteractionType" IN (\'Call\',\'Callback\')']))
